const baseName='oauth-records-reconnected-v3',candidateName='oauth-records-contract-v2';
const revisionAuthorization=await authorize(ready.revisionAlias,{reference:'Replacement API source and records.read consent review'});
await page.locator('#packages button.project').filter({hasText:baseName}).click();await settled();
const base=await read('/api/load?name='+encodeURIComponent(baseName)),routeId=base.preview.routes[0].id;
check((await read('/api/oauth/connection?alias='+encodeURIComponent(ready.alias))).grant.state==='disconnected','The historical source grant should remain disconnected during replacement review.');
const desk=page.locator('#source-revisions');
const firstReviewResponse=page.waitForResponse(response=>new URL(response.url()).pathname==='/api/revisions/review'&&response.request().method()==='POST');
await desk.getByLabel('Replacement OpenAPI JSON or YAML',{exact:true}).setInputFiles(ready.replacementSpecPath);
const firstReview=await (await firstReviewResponse).json();await settled();
check(firstReview.routes.length===1&&firstReview.routes[0].routeId===routeId&&!firstReview.ready,'The source desk did not retain the original route for an explicit decision.');
await desk.getByRole('combobox',{name:'Decision for '+routeId,exact:true}).selectOption('remap');
await desk.getByRole('textbox',{name:'Replacement operation for '+routeId,exact:true}).fill('GET /v2/records');
await desk.getByRole('combobox',{name:'Revision provider connection for '+routeId,exact:true}).selectOption(ready.revisionAlias);
const binding=await clickApi(desk.getByRole('button',{name:'Use revision grant for '+routeId,exact:true}),'/api/oauth/binding');
check(binding.body.oauthConnection.grantId===revisionAuthorization.grantId,'The replacement did not select its own source-bound reviewed grant.');
const reviewed=await clickApi(desk.getByRole('button',{name:'Review replacement',exact:true}),'/api/revisions/review');
check(reviewed.body.ready&&reviewed.body.authorization.ready,'The complete current replacement contract was not ready.');
check(reviewed.body.plan.operations[0].amountAtomic===base.plan.operations[0].amountAtomic,'The replacement changed the retained atomic price.');
check(JSON.stringify(reviewed.body.plan.operations[0].cache)===JSON.stringify(base.plan.operations[0].cache),'The replacement changed the explicit shared-read policy.');
await desk.getByLabel('New review snapshot name',{exact:true}).fill('records-v2-reviewed-source');
const draft=await clickApi(desk.getByRole('button',{name:'Save review snapshot',exact:true}),'/api/revisions/draft');
await desk.getByRole('combobox',{name:'Saved contract reviews',exact:true}).selectOption(draft.body.name);
await desk.getByRole('button',{name:'Reopen review',exact:true}).click();await settled();
await desk.getByLabel('New candidate package name',{exact:true}).fill(candidateName);
const saved=await clickApi(desk.getByRole('button',{name:'Save reviewed candidate',exact:true}),'/api/revisions/save');
const candidate=await read('/api/load?name='+encodeURIComponent(candidateName));
check(Buffer.from(candidate.specText,'utf8').equals(fs.readFileSync(ready.replacementSpecPath)),'The candidate did not retain the exact replacement source bytes.');
check(candidate.preview.routes[0].id===routeId,'The replacement lost the original route identity.');
check(candidate.plan.operations[0].oauthConnection.grantId===revisionAuthorization.grantId,'The candidate did not keep the explicitly reviewed replacement grant.');
check(candidate.sourceRevision.base.name===baseName&&candidate.sourceRevision.decisions[0].action==='remap','The source decision was not retained in the saved package.');
await desk.locator('summary').filter({hasText:'Stage with seller releases'}).click();
await desk.getByLabel('Original release store',{exact:true}).fill(path.join(PRIVATE,'reviewed-api-releases'));
await desk.getByLabel('Release ID',{exact:true}).fill('records-contract-v2');
await desk.getByLabel('Create this new release store',{exact:true}).check();
const staged=await clickApi(desk.getByRole('button',{name:'Stage this saved candidate',exact:true}),'/api/revisions/stage');
check(staged.body.record.id==='records-contract-v2','The original release store did not retain the exact staged candidate.');
await desk.scrollIntoViewIfNeeded();await screenshot('03-reviewed-api-revision-and-release.png');
const serving=await control('application.invoke',{package:candidateName});
check(serving.status===200&&serving.body.records.length===3,'The retained replacement package did not call the actual /v2/records provider route.');
const host=await control('host.prepare',{package:candidateName});
check(host.systemd.generated&&host.systemd.executed===false&&host.providerCallsDuringPreparation===0,'The original receiving-host preparation did not report its actual non-executed topology.');
const scan=await control('scan.public',{package:candidateName});
check(scan.leaks===0,'A private protocol value appeared in a public package/status output.');
await control('workspace.restart');await attach();
await page.locator('#packages button.project').filter({hasText:candidateName}).click();await settled();
const reopened=await read('/api/load?name='+encodeURIComponent(candidateName));
check(reopened.sourceRevision.reviewSha256===candidate.sourceRevision.reviewSha256,'Workspace restart changed the retained source review.');
const live=await read('/api/oauth/connection?alias='+encodeURIComponent(ready.revisionAlias));
check(live.grant.id===revisionAuthorization.grantId&&live.grant.state==='connected','Workspace restart did not retain the exact private reviewed grant.');
await page.setViewportSize({width:390,height:844});
await page.locator('#source-revisions').scrollIntoViewIfNeeded();
await screenshot('04-api-revision-mobile.png');
const layout=await page.evaluate(()=>({viewport:innerWidth,document:document.documentElement.scrollWidth}));
check(layout.document<=layout.viewport+1,'The joined operator page has a horizontal mobile overflow.');
await page.setViewportSize({width:1360,height:1000});
await page.locator('#oauth-connection-alias').selectOption(ready.revisionAlias);await settled();
await page.getByLabel('Also request remote revocation at the configured provider endpoint',{exact:true}).check();
await clickApi(page.locator('#oauth-disconnect'),'/api/oauth/command');
const closed=await read('/api/oauth/connection?alias='+encodeURIComponent(ready.revisionAlias));
check(closed.grant.state==='disconnected'&&closed.revocations.some(value=>value.grantId===revisionAuthorization.grantId&&value.state==='confirmed'),'The final local protocol authorization did not close with its exact remote cleanup.');
const result={baseName,candidateName,routeId,revisionAuthorization,
 source:{sha256:hash(fs.readFileSync(ready.replacementSpecPath)),originalBytesRetained:true},
 review:{sha256:candidate.sourceRevision.reviewSha256,action:'remap',from:'/records',to:'/v2/records',originalAtomicPrice:base.plan.operations[0].amountAtomic},
 stagedRelease:staged.body.record.id,records:serving.body,host,scan,
 restart:{sameGrant:true,sameReview:true},mobile:layout,finalGrantState:closed.grant.state,
 pageErrors:[...pageErrors],consoleErrors:[...consoleErrors],externalRequests:[...externalRequests]};
check(pageErrors.length===0,'The native operator run recorded a page script error.');
record('source_revision_release_receiving_host_restart_and_handover',result);
persist(path.join(DIR,'OPERATOR_RESULT.json'),{schema:'stellar-forge.oauth-operator-result.v1',completedAt:new Date().toISOString(),steps,pageErrors,consoleErrors,externalRequests});
return result;
